// src/components/ChordCard.js

import React from 'react';
import { chordDiagrams } from '../data/vocabulary';

const ChordCard = ({ chordName }) => {
  // Получаем схемы для данного аккорда из словаря
  const diagrams = chordDiagrams[chordName];

  // Если схем нет, ничего не рисуем
  if (!diagrams) return null;

  return (
    <div className="chord-card">
      {/* Заголовок - название аккорда */}
      <h3 className="chord-name">{chordName}</h3>

      {/* Контейнер для схем, чтобы они шли в строку */}
      <div className="diagrams-row">
        {diagrams.map((diagram, index) => (
          <div key={index} className="diagram-string">
            {diagram.split('').map((char, i) => {
              // Если символ 'x', красим его в красный
              if (char === 'x') {
                return <span key={i} className="fret-x">x</span>;
              }
              // Цифры и дефисы отображаем как есть
              return <span key={i} className="fret">{char}</span>;
            })}
          </div>
        ))}
      </div>
    </div>
  );
};

export default ChordCard;
